/* xx_notetab_extractor.c - search raw data for NoteTab.
 *
 * Scans for:
 *   3D 20 56 34 20 at +0  ("= V4 ")
 *   3D 20 56 35 20 at +0  ("= V5 ")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the notetab reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/notetab/xx_notetab.h"

static const uint8_t k_anchor0[] = { 0x3D, 0x20, 0x56, 0x34, 0x20 };
static const uint8_t k_anchor1[] = { 0x3D, 0x20, 0x56, 0x35, 0x20 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_NOTETAB };

static Abstractformat *xx_notetab_search_open(xx_io_device *window) {
    xx_notetab *reader = xx_notetab_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_notetab_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_notetab_free((xx_notetab *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_notetab_search_open, xx_notetab_search_close
};

static xx_format_search_state *xx_notetab_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_notetab_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_notetab_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_notetab_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_notetab_extractor = {
    xx_notetab_create_format_search,
    xx_notetab_get_current_format_info,
    xx_notetab_format_search_find_next,
    xx_notetab_free_format_search
};
